 void autoCalc(){double th=val(thick),r=val(punch),a=val(angle),bl=val(length),d=selectedDie();if(th>0&&r>=0&&a>0&&a<180&&bl>0&&d>0)calc();else if(resultBox!=null)emptyResult();}
