 double flatBD(){try{double th=Double.parseDouble(sharedT),r=Double.parseDouble(sharedR),a=Double.parseDouble(sharedA),d=Double.parseDouble(sharedD);double er=Math.max(r,d/6),rr=Math.toRadians(a);return 2*Math.tan(rr/2)*(er+th)-rr*(er+materialK.get(sharedMat)*th);}catch(Exception e){return Double.NaN;}}
